parameters.jsCode:
const item = $input.first().json;

// Validate topic
const recipientEmail = (item.recipient_email || '').trim();
const deliveryMethod = item.delivery_method || 'Save to Server Only';
if (recipientEmail && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(recipientEmail)) {
  throw new Error('Invalid recipient email address: ' + recipientEmail);
}
const topic = (item.topic || '').trim();
if (!topic) throw new Error('Research topic is required.');
if (topic.length < 10) throw new Error('Research topic must be at least 10 characters. Please be more specific.');
if (topic.length > 500) throw new Error('Research topic is too long (max 500 characters).');

// Generate a stable research ID
const researchId = 'ri_' + Date.now() + '_' + Math.random().toString(36).substr(2, 6);

// Parse depth
const depthRaw = item.research_depth || 'Standard Review (top 30 papers)';
let maxPapers = 30;
if (depthRaw.includes('15')) maxPapers = 15;
else if (depthRaw.includes('50')) maxPapers = 50;

// Parse dates
const dateFrom = parseInt(item.date_from) || 2018;
const dateTo = parseInt(item.date_to) || 2026;
if (dateFrom > dateTo) throw new Error('date_from must be earlier than date_to.');

return {
  json: {
    research_id: researchId,
    topic: topic,
    discipline: item.discipline || 'Computer Science',
    research_depth: depthRaw,
    max_papers: maxPapers,
    citation_format: item.citation_format || 'APA 7',
    date_from: dateFrom,
    date_to: dateTo,
    language: item.language || 'English',
    recipient_email: recipientEmail,
    delivery_method: deliveryMethod,
    report_format: item.report_format || 'Standard Summary',
    started_at: new Date().toISOString(),
    config: {
      max_papers: maxPapers,
      citation_format: item.citation_format || 'APA 7',
      date_from: dateFrom,
      date_to: dateTo,
      discipline: item.discipline || 'Computer Science'
    }
  }
};

const llmResponse = $input.first().json;
const validateNode = $('Validate & Configure').first().json;

let parsedData;
try {
  const content = llmResponse.choices?.[0]?.message?.content ||
                  llmResponse.choices?.[0]?.text ||
                  llmResponse.content ||
                  '{}';
  const contentStr = typeof content === 'string' ? content : JSON.stringify(content);
  const jsonMatch = contentStr.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsedData = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON object found in LLM response');
  }
} catch (e) {
  console.log('Query refinement LLM failed, using fallback:', e.message);
  const t = validateNode.topic;
  parsedData = {
    main_topic: t,
    refined_queries: [
      '"' + t + '" AND "research"',
      '"' + t + '" AND "deep learning"',
      '"' + t + '" AND "neural network"',
      '"' + t + '" AND "survey"',
      '"' + t + '" AND "systematic review"',
      '"' + t + '" AND "applications"',
      '"' + t + '" AND "benchmark"',
      t
    ],
    keywords: t.split(' ').slice(0, 5),
    sub_topics: [t + ' methods', t + ' applications'],
    exclusion_terms: [],
    time_range: validateNode.date_from + '-' + validateNode.date_to,
    expected_domains: [validateNode.discipline]
  };
}

// Normalize alternative field names the LLM may return
if (!parsedData.main_topic) {
  parsedData.main_topic = parsedData.topic || validateNode.topic;
}
if (!Array.isArray(parsedData.refined_queries)) {
  parsedData.refined_queries = parsedData.queries ||
                               parsedData.search_queries ||
                               parsedData.query_list ||
                               [];
}
if (!Array.isArray(parsedData.keywords)) {
  parsedData.keywords = parsedData.key_terms || parsedData.keyterms || [];
}

// Ensure we have at least 8 queries
while (parsedData.refined_queries.length < 8) {
  parsedData.refined_queries.push(parsedData.main_topic);
}

return {
  json: {
    ...parsedData,
    research_id: validateNode.research_id,
    topic: parsedData.main_topic || validateNode.topic,
    config: validateNode.config,
    discipline: validateNode.discipline,
    max_papers: validateNode.max_papers,
    citation_format: validateNode.citation_format,
    timestamp: new Date().toISOString()
  }
};

const normalizedPapers = [];
const seenDois = new Set();
const seenTitles = new Set();

function cleanText(text) {
  if (!text) return '';
  return String(text).replace(/\s+/g, ' ').trim();
}

function generateId() {
  return 'p_' + Math.random().toString(36).substr(2, 9);
}

function normalizeTitle(t) {
  return t.toLowerCase().replace(/[^a-z0-9]/g, '').substr(0, 60);
}

function addPaper(paper) {
  if (!paper.title || paper.title.length < 5) return;
  const nt = normalizeTitle(paper.title);
  if (paper.doi && seenDois.has(paper.doi)) return;
  if (seenTitles.has(nt)) return;
  if (paper.doi) seenDois.add(paper.doi);
  seenTitles.add(nt);
  normalizedPapers.push(paper);
}

// --- ArXiv (XML) ---
try {
  const arxivRaw = $('ArXiv Search').first().json.data || $('ArXiv Search').first().json || '';
  const arxivText = typeof arxivRaw === 'string' ? arxivRaw : JSON.stringify(arxivRaw);
  const entries = arxivText.split('<entry>').slice(1);
  entries.forEach(entry => {
    const titleM = entry.match(/<title>([\s\S]*?)<\/title>/);
    const abstractM = entry.match(/<summary>([\s\S]*?)<\/summary>/);
    const authorsM = [...entry.matchAll(/<name>([\s\S]*?)<\/name>/g)];
    const yearM = entry.match(/<published>(\d{4})/);
    const idM = entry.match(/<id>https?:\/\/arxiv\.org\/abs\/([^<\s]+)<\/id>/);
    const title = titleM ? cleanText(titleM[1]) : '';
    if (!title) return;
    addPaper({
      id: generateId(),
      title,
      authors: authorsM.map(m => m[1].trim()).join(', '),
      year: yearM ? yearM[1] : 'N/A',
      abstract: abstractM ? cleanText(abstractM[1]) : 'Abstract not available',
      doi: idM ? 'arxiv:' + idM[1] : '',
      citations: 0,
      journal: 'arXiv preprint',
      source: 'ArXiv',
      is_open_access: true,
      pdf_url: idM ? 'https://arxiv.org/pdf/' + idM[1] : ''
    });
  });
} catch(e) { console.log('ArXiv parse error:', e.message); }

// --- CrossRef ---
try {
  const cr = $('CrossRef Search').first().json;
  (cr.message?.items || []).forEach(paper => {
    const title = cleanText(Array.isArray(paper.title) ? paper.title[0] : paper.title);
    const doi = paper.DOI;
    if (!title) return;
    const authors = (paper.author || []).map(a => [a.given, a.family].filter(Boolean).join(' ')).join(', ');
    addPaper({
      id: generateId(),
      title,
      authors,
      year: paper.published?.['date-parts']?.[0]?.[0] || paper['published-print']?.['date-parts']?.[0]?.[0] || 'N/A',
      abstract: cleanText((paper.abstract || '').replace(/<[^>]+>/g, '')) || 'Abstract not available',
      doi: doi || '',
      citations: paper['is-referenced-by-count'] || 0,
      journal: paper['container-title']?.[0] || paper.publisher || '',
      source: 'CrossRef',
      is_open_access: false,
      pdf_url: ''
    });
  });
} catch(e) { console.log('CrossRef parse error:', e.message); }

// --- PubMed eSummary ---
try {
  const pm = $('PubMed eSummary').first().json;
  const result = pm.result || {};
  const uids = result.uids || [];
  uids.forEach(uid => {
    const p = result[uid];
    if (!p) return;
    const title = cleanText(p.title);
    if (!title) return;
    const authors = (p.authors || []).map(a => a.name).join(', ');
    const doi = (p.articleids || []).find(x => x.idtype === 'doi')?.value || '';
    addPaper({
      id: generateId(),
      title,
      authors,
      year: p.pubdate ? p.pubdate.substring(0, 4) : 'N/A',
      abstract: 'Abstract not available via eSummary. See PubMed for full details.',
      doi,
      citations: 0,
      journal: p.source || '',
      source: 'PubMed',
      is_open_access: false,
      pdf_url: p.pmcid ? 'https://www.ncbi.nlm.nih.gov/pmc/articles/' + p.pmcid + '/pdf/' : ''
    });
  });
} catch(e) { console.log('PubMed parse error:', e.message); }

// --- OpenAlex ---
try {
  const oa = $('OpenAlex Search').first().json;
  (oa.results || []).forEach(paper => {
    const title = cleanText(paper.title);
    const doi = paper.doi?.replace('https://doi.org/', '');
    if (!title) return;
    let abstract = 'Abstract not available';
    if (paper.abstract_inverted_index) {
      const words = {};
      Object.entries(paper.abstract_inverted_index).forEach(([word, positions]) => {
        positions.forEach(pos => { words[pos] = word; });
      });
      abstract = Object.keys(words).sort((a, b) => Number(a) - Number(b)).map(k => words[k]).join(' ');
    }
    addPaper({
      id: generateId(),
      title,
      authors: (paper.authorships || []).map(a => a.author?.display_name).filter(Boolean).join(', '),
      year: paper.publication_year || 'N/A',
      abstract: cleanText(abstract),
      doi: doi || '',
      citations: paper.cited_by_count || 0,
      journal: paper.primary_location?.source?.display_name || '',
      source: 'OpenAlex',
      is_open_access: paper.primary_location?.is_oa || false,
      pdf_url: paper.primary_location?.pdf_url || ''
    });
  });
} catch(e) { console.log('OpenAlex parse error:', e.message); }

// --- Semantic Scholar ---
try {
  const ss = $('Semantic Scholar Search').first().json;
  (ss.data || []).forEach(paper => {
    const title = cleanText(paper.title);
    const doi = paper.externalIds?.DOI || '';
    if (!title) return;
    addPaper({
      id: generateId(),
      title,
      authors: (paper.authors || []).map(a => a.name).join(', '),
      year: paper.year || 'N/A',
      abstract: cleanText(paper.abstract) || 'Abstract not available',
      doi,
      citations: paper.citationCount || 0,
      journal: paper.journal?.name || '',
      source: 'Semantic Scholar',
      is_open_access: paper.isOpenAccess || false,
      pdf_url: paper.openAccessPdf?.url || ''
    });
  });
} catch(e) { console.log('Semantic Scholar parse error:', e.message); }

// Sort and limit
normalizedPapers.sort((a, b) => {
  if (b.citations !== a.citations) return b.citations - a.citations;
  return (Number(b.year) || 0) - (Number(a.year) || 0);
});

const queryData = $('Parse Query Output').first().json;
const maxPapers = queryData.max_papers || 30;
const topPapers = normalizedPapers.slice(0, maxPapers);

const sourcesCovered = [...new Set(topPapers.map(p => p.source))];

console.log('Aggregation complete:', normalizedPapers.length, 'unique papers found,', topPapers.length, 'selected from', sourcesCovered.join(', '));

return {
  json: {
    papers: topPapers,
    total_found: normalizedPapers.length,
    total_used: topPapers.length,
    topic: queryData.topic || queryData.main_topic,
    keywords: queryData.keywords || [],
    sub_topics: queryData.sub_topics || [],
    research_id: queryData.research_id,
    config: queryData.config,
    citation_format: queryData.citation_format,
    max_papers: maxPapers,
    search_timestamp: new Date().toISOString(),
    sources_queried: ['ArXiv', 'CrossRef', 'PubMed', 'OpenAlex', 'Semantic Scholar'],
    sources_with_results: sourcesCovered
  }
};

return $input.all().map((item, index) => {
  const analysisResponse = item.json;

  // Try pairedItem reference first (most reliable)
  const pairedIndex = item.pairedItem?.item ?? index;
  let paperData = $('Split Papers for Processing').all()[pairedIndex]?.json || {};

  // Parse the LLM analysis response
  let analysis = {};
  try {
    const content = analysisResponse.choices?.[0]?.message?.content || '{}';
    const contentStr = typeof content === 'string' ? content : JSON.stringify(content);
    const jsonMatch = contentStr.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      analysis = JSON.parse(jsonMatch[0]);
    }
  } catch(e) {
    analysis = {};
  }

  // If analysis includes paper_id, use it to find the correct paper (ID-based matching)
  if (analysis.paper_id && analysis.paper_id !== 'unknown') {
    const matchedPaper = $('Split Papers for Processing').all().find(p => p.json?.id === analysis.paper_id);
    if (matchedPaper) {
      paperData = matchedPaper.json;
    }
  }

  // Fallback analysis if LLM failed
  if (!analysis.methodology) {
    analysis = {
      paper_id: paperData.id || 'unknown',
      paper_category: 'Unknown',
      research_problem: 'Could not extract — LLM analysis unavailable',
      methodology: 'Not extractable',
      datasets_used: [],
      evaluation_metrics: [],
      key_findings: ['Analysis unavailable — review abstract manually'],
      strengths: [],
      limitations: [],
      future_work: [],
      innovation_score: null,
      relevance_score: null,
      summary: (paperData.abstract || '').substring(0, 200) || 'No summary available'
    };
  }

  return {
    json: {
      ...paperData,
      analysis,
      processed: true,
      processed_at: new Date().toISOString()
    }
  };
});

