parameters.jsCode:
const allPapers = ($('Collect All Analyzed Papers').first().json.data || []).sort((a, b) => (Number(b.year) || 0) - (Number(a.year) || 0));
const queryData = $('Aggregate & Deduplicate').first().json;
const validateData = $('Validate & Configure').first().json;

function parseAgentJson(nodeGetter) {
  try {
    const r = nodeGetter();
    const content = r.choices?.[0]?.message?.content || r.content || '{}';
    const str = typeof content === 'string' ? content : JSON.stringify(content);
    const m = str.match(/\{[\s\S]*\}/);
    return m ? JSON.parse(m[0]) : {};
  } catch(e) { const validateData2 = $('Validate & Configure').first().json;
return {}; }
}

const synthesis = parseAgentJson(() => $('Synthesize Literature').first().json);
const gaps = parseAgentJson(() => $('Identify Research Gaps').first().json);
const citData = parseAgentJson(() => $('Generate Citations').first().json);
const matrixData = parseAgentJson(() => $('Build Literature Matrix').first().json);

// Build synced citations from papers (fallback if LLM citation failed)
const syncedCitations = allPapers.map((p, i) => {
  const existing = (citData.formatted_references || [])[i];
  const citStr = existing || ('[' + (i+1) + '] ' + (p.authors || 'Unknown') + ', "' + p.title + '," ' + (p.journal || 'Journal') + ', ' + p.year + (p.doi ? '. doi: ' + p.doi : '') + '.');
  return { index: i + 1, citation: citStr, title: p.title, doi: p.doi };
});

const years = allPapers.map(p => parseInt(p.year)).filter(y => !isNaN(y));
const minYear = years.length > 0 ? Math.min(...years) : 2018;
const maxYear = years.length > 0 ? Math.max(...years) : 2026;

return {
  json: {
    research_id: queryData.research_id || validateData.research_id,
    topic: queryData.topic,
    papers: allPapers,
    total_papers: allPapers.length,
    year_range: { min: minYear, max: maxYear },
    sources_queried: queryData.sources_queried || [],
    keywords: queryData.keywords || [],
    synthesis,
    gaps,
    citations: syncedCitations,
    citation_format: queryData.citation_format || 'APA 7',
    matrix: matrixData,
    config: queryData.config || validateData.config,
    generated_at: new Date().toISOString(),
    llm_model: $env.LLM_MODEL || 'unknown',
    report_format: validateData2.report_format || 'Standard Summary',
    ai_disclosure: {
      tool: 'Research Intelligence n8n v2.0.0',
      model: $env.LLM_MODEL || 'unknown',
      provider: $env.LLM_API_BASE_URL || 'unknown',
      activities: ['Query refinement', 'Paper analysis', 'Literature synthesis', 'Gap identification', 'Citation formatting'],
      limitations: 'Analysis based on abstracts only. Full-text review recommended. Citations generated by AI — verify against original sources before use. Research gaps are preliminary assessments requiring human evaluation.',
      human_review_required: true
    }
  }
};

const data = $('Assemble Complete Review Data').first().json;
const validateData = $('Validate & Configure').first().json;
const topic = data.topic || 'Research Topic';
const synthesis = data.synthesis || {};
const papers = data.papers || [];
const citations = data.citations || [];
const gaps = data.gaps || {};
const matrix = data.matrix || {};
const aiDisclosure = data.ai_disclosure || {};
const feedback = $input.first().json.body?.feedback || '';
const isFullReport = (validateData.report_format || 'Standard Summary').includes('Full');

// ── HTML escape ──────────────────────────────────────────────────────────────
function esc(str) {
  if (!str) return '';
  return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

// ── Inline citation linker ───────────────────────────────────────────────────
// Convert [N] markers in LLM-generated prose to anchor links
function linkCite(text) {
  if (!text) return '';
  return esc(text).replace(/\[(\d+(?:,\s*\d+)*)\]/g, (match, nums) => {
    const links = nums.split(',').map(n => {
      const idx = n.trim();
      return `<a href="#ref-${idx}" class="cite">[${idx}]</a>`;
    });
    return links.join('');
  });
}

// ── Stats ────────────────────────────────────────────────────────────────────
const years = papers.map(p => parseInt(p.year)).filter(y => !isNaN(y));
const minYear = years.length > 0 ? Math.min(...years) : 2018;
const maxYear = years.length > 0 ? Math.max(...years) : 2026;
const totalCitations = papers.reduce((s, p) => s + (p.citations || 0), 0);
const avgCitations = papers.length > 0 ? Math.round(totalCitations / papers.length) : 0;
const sources = [...new Set(papers.map(p => p.source).filter(Boolean))];
const openAccessCount = papers.filter(p => p.is_open_access).length;

// ── SVG CHARTS ───────────────────────────────────────────────────────────────

function yearHistogramSVG() {
  if (years.length < 2) return '';
  const yearCounts = {};
  years.forEach(y => { yearCounts[y] = (yearCounts[y] || 0) + 1; });
  const sortedYears = Object.keys(yearCounts).sort();
  const maxCount = Math.max(...Object.values(yearCounts));
  const W = 520, H = 205, PL = 44, PR = 14, PT = 36, PB = 52;
  const plotW = W - PL - PR, plotH = H - PT - PB;
  const barW = Math.max(8, Math.min(36, plotW / sortedYears.length - 4));
  const xStep = plotW / sortedYears.length;
  const step = Math.ceil(maxCount / 5);

  const gridLines = [1,2,3,4,5].map(i => {
    const val = i * step; if (val > maxCount * 1.15) return '';
    const gy = (PT + plotH - (val / maxCount) * plotH).toFixed(1);
    return `<line x1="${PL}" y1="${gy}" x2="${W-PR}" y2="${gy}" stroke="rgba(0,0,0,0.055)" stroke-width="0.8"/>
<text x="${(PL-7).toFixed(1)}" y="${(parseFloat(gy)+3).toFixed(1)}" text-anchor="end" font-size="9" fill="#6b7280">${val}</text>`;
  }).join('\n');

  const bars = sortedYears.map((yr, i) => {
    const count = yearCounts[yr];
    const bh = (count / maxCount) * plotH;
    const x = PL + i * xStep + (xStep - barW) / 2;
    const y = PT + plotH - bh;
    return `<rect x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${barW}" height="${bh.toFixed(1)}" fill="url(#yh-grad)" rx="2.5" opacity="0.9"/>
<text x="${(x+barW/2).toFixed(1)}" y="${(y-5).toFixed(1)}" text-anchor="middle" font-size="9" font-weight="600" fill="#1d4ed8">${count}</text>
<text x="${(x+barW/2).toFixed(1)}" y="${(H-PB+15).toFixed(1)}" text-anchor="middle" font-size="8" fill="#6b7280">${yr}</text>`;
  }).join('\n');

  return `<figure class="chart-fig">
<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg" class="chart-svg" role="img" aria-label="Publications per year bar chart">
  <defs>
    <linearGradient id="yh-grad" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="#1a3a5c"/><stop offset="100%" stop-color="#2d6a9f"/>
    </linearGradient>
  </defs>
  <text x="${W/2}" y="20" text-anchor="middle" font-size="12" font-weight="600" fill="#0c1426">Publications per Year</text>
  ${gridLines}
  <line x1="${PL}" y1="${PT}" x2="${PL}" y2="${PT+plotH}" stroke="rgba(12,20,38,0.18)" stroke-width="1"/>
  <line x1="${PL}" y1="${PT+plotH}" x2="${W-PR}" y2="${PT+plotH}" stroke="rgba(12,20,38,0.18)" stroke-width="1"/>
  ${bars}
  <text x="${W/2}" y="${H-5}" text-anchor="middle" font-size="9.5" fill="#6b7280">Year</text>
</svg>
<figcaption>Figure 1 — Annual publication counts for the ${papers.length} papers retrieved (${minYear}–${maxYear}).</figcaption>
</figure>`;
}

function sourceBarSVG() {
  const srcCounts = {};
  papers.forEach(p => { const s = p.source || 'Unknown'; srcCounts[s] = (srcCounts[s] || 0) + 1; });
  const sorted = Object.entries(srcCounts).sort((a,b) => b[1]-a[1]);
  if (!sorted.length) return '';
  const palette = ['#1a3a5c','#2d6a9f','#3d8bbf','#c0392b','#27ae60','#8e44ad','#e67e22'];
  const maxCount = sorted[0][1];
  const W = 380, ROW_H = 28, PL = 130, PR = 60, H = sorted.length * ROW_H + 54;
  const plotW = W - PL - PR;

  const gridLines = [.25,.5,.75,1].map(f =>
    `<line x1="${(PL + f*plotW).toFixed(1)}" y1="32" x2="${(PL + f*plotW).toFixed(1)}" y2="${H-18}" stroke="rgba(0,0,0,0.055)" stroke-width="0.8"/>`
  ).join('\n');

  const bars = sorted.map(([src, cnt], i) => {
    const bw = Math.max(4, (cnt / maxCount) * plotW);
    const y = 42 + i * ROW_H;
    return `<text x="${PL-7}" y="${y+13}" text-anchor="end" font-size="9" fill="#3b5068">${esc(src)}</text>
<rect x="${PL}" y="${y}" width="${bw.toFixed(1)}" height="20" fill="${palette[i % palette.length]}" rx="2.5" opacity="0.88"/>
<text x="${(PL+bw+7).toFixed(1)}" y="${y+13}" font-size="9" font-weight="600" fill="#1d4ed8">${cnt} · ${Math.round(cnt/papers.length*100)}%</text>`;
  }).join('\n');

  return `<figure class="chart-fig">
<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg" class="chart-svg" role="img" aria-label="Papers by database">
  <text x="${W/2}" y="20" text-anchor="middle" font-size="12" font-weight="600" fill="#0c1426">Papers by Database</text>
  ${gridLines}
  <line x1="${PL}" y1="32" x2="${PL}" y2="${H-18}" stroke="rgba(12,20,38,0.18)" stroke-width="1"/>
  <line x1="${PL}" y1="${H-18}" x2="${W-PR}" y2="${H-18}" stroke="rgba(12,20,38,0.18)" stroke-width="1"/>
  ${bars}
  <text x="${(PL+plotW/2).toFixed(1)}" y="${H-4}" text-anchor="middle" font-size="9" fill="#6b7280">Count</text>
</svg>
<figcaption>Figure 2 — Breakdown of ${papers.length} papers by source database.</figcaption>
</figure>`;
}

function categoryBarSVG() {
  const catCounts = {};
  papers.forEach(p => { const c = p.analysis?.paper_category || 'Unclassified'; catCounts[c] = (catCounts[c] || 0) + 1; });
  const sorted = Object.entries(catCounts).sort((a,b) => b[1]-a[1]).slice(0, 8);
  if (!sorted.length) return '';
  const palette = ['#1a3a5c','#2d6a9f','#3d8bbf','#c0392b','#27ae60','#8e44ad','#e67e22','#1a3a5c'];
  const maxCount = sorted[0][1];
  const W = 420, ROW_H = 28, PL = 155, PR = 55, H = sorted.length * ROW_H + 54;
  const plotW = W - PL - PR;

  const gridLines = [.25,.5,.75,1].map(f =>
    `<line x1="${(PL + f*plotW).toFixed(1)}" y1="32" x2="${(PL + f*plotW).toFixed(1)}" y2="${H-18}" stroke="rgba(0,0,0,0.055)" stroke-width="0.8"/>`
  ).join('\n');

  const bars = sorted.map(([cat, cnt], i) => {
    const bw = Math.max(4, (cnt / maxCount) * plotW);
    const y = 42 + i * ROW_H;
    return `<text x="${PL-7}" y="${y+13}" text-anchor="end" font-size="8.5" fill="#3b5068">${esc(cat)}</text>
<rect x="${PL}" y="${y}" width="${bw.toFixed(1)}" height="20" fill="${palette[i % palette.length]}" rx="2.5" opacity="0.88"/>
<text x="${(PL+bw+7).toFixed(1)}" y="${y+13}" font-size="9" font-weight="600" fill="#1d4ed8">${cnt}</text>`;
  }).join('\n');

  return `<figure class="chart-fig">
<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg" class="chart-svg" role="img" aria-label="Paper categories">
  <text x="${W/2}" y="20" text-anchor="middle" font-size="12" font-weight="600" fill="#0c1426">Paper Categories</text>
  ${gridLines}
  <line x1="${PL}" y1="32" x2="${PL}" y2="${H-18}" stroke="rgba(12,20,38,0.18)" stroke-width="1"/>
  <line x1="${PL}" y1="${H-18}" x2="${W-PR}" y2="${H-18}" stroke="rgba(12,20,38,0.18)" stroke-width="1"/>
  ${bars}
  <text x="${(PL+plotW/2).toFixed(1)}" y="${H-4}" text-anchor="middle" font-size="9" fill="#6b7280">Count</text>
</svg>
<figcaption>Figure 3 — Distribution of paper types as classified by AI analysis.</figcaption>
</figure>`;
}

function scatterSVG() {
  const pts = papers.filter(p => p.analysis?.innovation_score != null && p.analysis?.relevance_score != null);
  if (pts.length < 4) return '';
  const W = 340, H = 265, PL = 46, PR = 20, PT = 36, PB = 44;
  const plotW = W - PL - PR, plotH = H - PT - PB;

  const grid = [2,4,6,8,10].map(v => {
    const gx = (PL + (v/10) * plotW).toFixed(1);
    const gy = (PT + plotH - (v/10) * plotH).toFixed(1);
    return `<line x1="${gx}" y1="${PT}" x2="${gx}" y2="${PT+plotH}" stroke="rgba(0,0,0,0.055)" stroke-width="0.8"/>
<text x="${gx}" y="${PT+plotH+14}" text-anchor="middle" font-size="8.5" fill="#6b7280">${v}</text>
<line x1="${PL}" y1="${gy}" x2="${W-PR}" y2="${gy}" stroke="rgba(0,0,0,0.055)" stroke-width="0.8"/>
<text x="${PL-5}" y="${parseFloat(gy)+3}" text-anchor="end" font-size="8.5" fill="#6b7280">${v}</text>`;
  }).join('\n');

  const dots = pts.map(p => {
    const x = (PL + (p.analysis.innovation_score / 10) * plotW).toFixed(1);
    const y = (PT + plotH - (p.analysis.relevance_score / 10) * plotH).toFixed(1);
    const auth = esc(((p.authors || '').split(',')[0] || 'Unknown').trim());
    return `<circle cx="${x}" cy="${y}" r="5" fill="#1a3a5c" fill-opacity="0.6" stroke="#ffffff" stroke-width="1.2"><title>${auth} (${p.year || '?'})</title></circle>`;
  }).join('\n');

  return `<figure class="chart-fig">
<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg" class="chart-svg" role="img" aria-label="Innovation vs Relevance scatter">
  <text x="${W/2}" y="20" text-anchor="middle" font-size="12" font-weight="600" fill="#0c1426">Innovation vs Relevance</text>
  ${grid}
  <line x1="${PL}" y1="${PT}" x2="${PL}" y2="${PT+plotH}" stroke="rgba(12,20,38,0.18)" stroke-width="1"/>
  <line x1="${PL}" y1="${PT+plotH}" x2="${W-PR}" y2="${PT+plotH}" stroke="rgba(12,20,38,0.18)" stroke-width="1"/>
  ${dots}
  <text x="${W/2}" y="${H-5}" text-anchor="middle" font-size="9.5" fill="#6b7280">Innovation Score</text>
  <text x="12" y="${PT+plotH/2}" text-anchor="middle" font-size="9.5" fill="#6b7280" transform="rotate(-90 12 ${PT+plotH/2})">Relevance</text>
</svg>
<figcaption>Figure 4 — Innovation score vs relevance score for ${pts.length} analysed papers. Each point is one paper; hover for author.</figcaption>
</figure>`;
}

function citationHistSVG() {
  const citVals = papers.map(p => p.citations || 0).filter(c => c >= 0);
  if (citVals.length < 4) return '';
  const breakpoints = [1, 10, 50, 100, 500, 1000, Infinity];
  const labels = ['0','1–9','10–49','50–99','100–499','500–999','1000+'];
  const counts = new Array(labels.length).fill(0);
  citVals.forEach(c => {
    for (let i = 0; i < breakpoints.length - 1; i++) {
      if (c >= breakpoints[i] && c < breakpoints[i+1]) { counts[i]++; break; }
    }
    if (c < 1) counts[0]++;
  });
  const maxCount = Math.max(...counts, 1);
  const W = 420, H = 190, PL = 42, PR = 14, PT = 36, PB = 46;
  const plotW = W - PL - PR, plotH = H - PT - PB;
  const barW = plotW / labels.length - 5;

  const gridLines = [.25,.5,.75,1].map(f => {
    const val = Math.round(f * maxCount);
    const gy = (PT + plotH - f * plotH).toFixed(1);
    return `<line x1="${PL}" y1="${gy}" x2="${W-PR}" y2="${gy}" stroke="rgba(0,0,0,0.055)" stroke-width="0.8"/>
<text x="${(PL-7).toFixed(1)}" y="${(parseFloat(gy)+3).toFixed(1)}" text-anchor="end" font-size="9" fill="#6b7280">${val}</text>`;
  }).join('\n');

  const bars = labels.map((lbl, i) => {
    const cnt = counts[i]; if (!cnt) return '';
    const bh = (cnt / maxCount) * plotH;
    const x = PL + i * (plotW / labels.length) + 2.5;
    const y = PT + plotH - bh;
    return `<rect x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${barW.toFixed(1)}" height="${bh.toFixed(1)}" fill="url(#ch-grad)" rx="2.5" opacity="0.88"/>
<text x="${(x+barW/2).toFixed(1)}" y="${(y-5).toFixed(1)}" text-anchor="middle" font-size="9" font-weight="600" fill="#1d4ed8">${cnt}</text>
<text x="${(x+barW/2).toFixed(1)}" y="${H-PB+16}" text-anchor="middle" font-size="7.5" fill="#6b7280">${lbl}</text>`;
  }).join('\n');

  return `<figure class="chart-fig">
<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg" class="chart-svg" role="img" aria-label="Citation count distribution">
  <defs>
    <linearGradient id="ch-grad" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="#c0392b"/><stop offset="100%" stop-color="#e74c3c"/>
    </linearGradient>
  </defs>
  <text x="${W/2}" y="20" text-anchor="middle" font-size="12" font-weight="600" fill="#0c1426">Citation Count Distribution</text>
  ${gridLines}
  <line x1="${PL}" y1="${PT}" x2="${PL}" y2="${PT+plotH}" stroke="rgba(12,20,38,0.18)" stroke-width="1"/>
  <line x1="${PL}" y1="${PT+plotH}" x2="${W-PR}" y2="${PT+plotH}" stroke="rgba(12,20,38,0.18)" stroke-width="1"/>
  ${bars}
  <text x="${W/2}" y="${H-5}" text-anchor="middle" font-size="9.5" fill="#6b7280">Citation Buckets</text>
</svg>
<figcaption>Figure 5 — Distribution of total citation counts (all-time, at time of retrieval).</figcaption>
</figure>`;
}

