// ── Thematic Sections ─────────────────────────────────────────────────────────
function thematicHTML() {
  const sections = synthesis.thematic_sections || [];
  if (!sections.length) return `<p class="unavail">Thematic analysis not available for ${papers.length} retrieved papers.</p>`;
  return sections.map((s, i) => {
    const keyPapersHTML = (s.key_papers || []).map(t => {
      const idx = papers.findIndex(p => p.title && p.title.toLowerCase().includes(t.toLowerCase().substring(0, 25)));
      return idx >= 0 ? `<a href="#ref-${idx+1}" class="cite">${esc(t)}</a>` : `<em>${esc(t)}</em>`;
    }).join('; ');
    return `<div class="theme-block" id="sec-t${i}">
  <h3>${isFullReport ? `3.${i+1}` : ''} ${esc(s.title || 'Theme ' + (i+1))}</h3>
  <div class="theme-body">${linkCite(s.content || '')}</div>
  ${s.consensus_view ? `<div class="insight consensus-box"><strong>Consensus view:</strong> ${linkCite(s.consensus_view)}</div>` : ''}
  ${s.contested_areas ? `<div class="insight contested-box"><strong>Contested:</strong> ${linkCite(s.contested_areas)}</div>` : ''}
  ${keyPapersHTML ? `<div class="key-src"><strong>Key sources:</strong> ${keyPapersHTML}</div>` : ''}
</div>`;
  }).join('\n');
}

// ── Gaps ──────────────────────────────────────────────────────────────────────
function gapsHTML() {
  const pGaps = gaps.priority_gaps || synthesis.research_gaps || [];
  if (!pGaps.length) return '<p class="unavail">No specific research gaps identified. Full-text review recommended.</p>';
  const allGaps = [...(gaps.empirical_gaps || []), ...(gaps.theoretical_gaps || []), ...(gaps.methodological_gaps || [])];
  const typedGaps = allGaps.length > 0 ? allGaps : pGaps;
  return typedGaps.map((g, i) => {
    const gapText = typeof g === 'string' ? g : (g.gap || JSON.stringify(g));
    const gType = typeof g === 'object' && g.type ? g.type : (typeof g === 'object' && g.rationale ? 'identified' : '');
    const rationale = typeof g === 'object' ? (g.rationale || '') : '';
    const strength = typeof g === 'object' ? (g.evidence_strength || '') : '';
    const suppPapers = typeof g === 'object' ? (g.supporting_papers || []) : [];
    return `<div class="gap-card">
  <div class="gap-header">
    <span class="gap-num">Gap ${i+1}</span>
    ${gType ? `<span class="gap-type-tag">${esc(gType)}</span>` : ''}
    ${strength ? `<span class="ev-strength ev-${esc(strength)}">${esc(strength)}</span>` : ''}
  </div>
  <p class="gap-text">${linkCite(gapText)}</p>
  ${rationale ? `<p class="gap-rationale"><em>${linkCite(rationale)}</em></p>` : ''}
  ${suppPapers.length ? `<p class="gap-src">Evidenced by: ${suppPapers.slice(0,3).map(t => { const idx = papers.findIndex(p => p.title && p.title.toLowerCase().includes(t.toLowerCase().substring(0,20))); return idx >= 0 ? `<a href="#ref-${idx+1}" class="cite">${esc(t)}</a>` : `<em>${esc(t)}</em>`; }).join('; ')}</p>` : ''}
</div>`;
  }).join('\n');
}

// ── Literature Matrix ─────────────────────────────────────────────────────────
function matrixHTML() {
  const rows = papers.slice(0, 50).map((p, i) => ({
    n: i + 1,
    auth: (p.authors || '').split(',')[0].trim() + ((p.authors || '').includes(',') ? ' et al.' : ''),
    yr: p.year || '—',
    title: (p.title || '').substring(0, 60) + ((p.title || '').length > 60 ? '…' : ''),
    method: p.analysis?.methodology || '—',
    datasets: (p.analysis?.datasets_used || []).slice(0,2).join(', ') || '—',
    metrics: (p.analysis?.evaluation_metrics || []).slice(0,2).join(', ') || '—',
    cat: p.analysis?.paper_category || '—',
    inn: p.analysis?.innovation_score,
    rel: p.analysis?.relevance_score,
    lim: (p.analysis?.limitations || ['—'])[0] || '—',
    cit: p.citations || 0,
    doi: p.doi || '',
    oa: p.is_open_access
  }));

  const scoreSpan = (v) => {
    if (v == null) return '<span class="score-na">—</span>';
    const col = v >= 7 ? '#1b5e20' : v >= 4 ? '#e65100' : '#b71c1c';
    return `<span class="score-badge" style="color:${col};border-color:${col}">${v}</span>`;
  };

  const ths = ['#','Authors','Year','Title','Method','Datasets','Metrics','Category','Inn','Rel','Limitations','Cit.'];
  const thead = `<tr>${ths.map(h => `<th>${esc(h)}</th>`).join('')}</tr>`;
  const tbody = rows.map((r, i) =>
    `<tr>
      <td><a href="#ref-${r.n}" class="cite">[${r.n}]</a>${r.oa ? ' <span class="oa-m" title="Open Access">OA</span>' : ''}</td>
      <td>${esc(r.auth)}</td>
      <td>${esc(r.yr)}</td>
      <td class="tc">${r.doi ? `<a href="https://doi.org/${esc(r.doi)}" target="_blank">${esc(r.title)}</a>` : esc(r.title)}</td>
      <td>${esc(r.method)}</td>
      <td>${esc(r.datasets)}</td>
      <td>${esc(r.metrics)}</td>
      <td><span class="cat-tag">${esc(r.cat)}</span></td>
      <td>${scoreSpan(r.inn)}</td>
      <td>${scoreSpan(r.rel)}</td>
      <td class="lim-col">${esc(r.lim)}</td>
      <td class="num-col">${r.cit.toLocaleString()}</td>
    </tr>`
  ).join('\n');

  return `<div class="table-wrap"><table class="mt"><thead>${thead}</thead><tbody>${tbody}</tbody></table></div>`;
}

// ── Evidence Cards ────────────────────────────────────────────────────────────
function evidenceCards() {
  const srcColors = { 'ArXiv':'#b71c1c','CrossRef':'#1565c0','PubMed':'#1b5e20','OpenAlex':'#4a148c','Semantic Scholar':'#e65100' };
  return papers.map((p, i) => {
    const a = p.analysis || {};
    const scoreColor = s => s >= 7 ? '#1b5e20' : s >= 4 ? '#e65100' : '#b71c1c';
    const srcCol = srcColors[p.source] || '#546e7a';
    const verBadge = p.verification_status === 'verified' || p.verification_status === 'doi_resolves'
      ? '<span class="ver-badge">✓ Verified</span>' : '';
    return `<article class="ev-card" id="ref-${i+1}">
  <header class="ev-card-head">
    <span class="ev-ref">[${i+1}]</span>
    <span class="ev-src-tag" style="background:${srcCol}">${esc(p.source)}</span>
    ${p.is_open_access ? '<span class="oa-badge">Open Access</span>' : ''}
    ${verBadge}
    ${a.innovation_score != null ? `<span class="ev-score" style="color:${scoreColor(a.innovation_score)}">Inn. ${a.innovation_score}/10</span>` : ''}
    ${a.relevance_score != null ? `<span class="ev-score" style="color:${scoreColor(a.relevance_score)}">Rel. ${a.relevance_score}/10</span>` : ''}
  </header>
  <h4 class="ev-title">${p.url ? `<a href="${esc(p.url)}" target="_blank" rel="noopener">${esc(p.title)}</a>` : esc(p.title)}</h4>
  <p class="ev-meta">${esc(p.authors)} · <strong>${esc(p.year)}</strong> · <em>${esc(p.journal || p.source)}</em>${p.citations ? ` · ${p.citations.toLocaleString()} citations` : ''}${p.doi ? ` · <a href="https://doi.org/${esc(p.doi)}" target="_blank" rel="noopener" class="doi-link">DOI</a>` : ''}</p>
  ${p.abstract && p.abstract !== 'Abstract not available' ? `<p class="ev-abstract">${esc(p.abstract.substring(0, 500))}${p.abstract.length > 500 ? '…' : ''}</p>` : ''}
  ${a.key_findings?.length ? `<div class="ev-section"><strong>Key findings:</strong><ul>${a.key_findings.slice(0,4).map(f => `<li>${esc(f)}</li>`).join('')}</ul></div>` : ''}
  ${a.methodology ? `<div class="ev-section"><strong>Methodology:</strong> ${esc(a.methodology)}</div>` : ''}
  ${a.limitations?.length ? `<div class="ev-section ev-lim"><strong>Limitations:</strong> ${esc(a.limitations[0])}</div>` : ''}
  ${a.future_work?.length ? `<div class="ev-section ev-fut"><strong>Future work:</strong> ${esc(a.future_work[0])}</div>` : ''}
</article>`;
  }).join('\n');
}

// ── Taxonomy ──────────────────────────────────────────────────────────────────
function taxonomyHTML() {
  const tax = synthesis.taxonomy || {};
  if (!tax.categories?.length) return '';
  const cats = tax.categories.map(c =>
    `<div class="tax-item"><span class="tax-name">${esc(c.name)}</span> <span class="tax-count">${c.paper_count || 0} papers</span><p>${esc(c.description)}</p></div>`
  ).join('\n');
  return `<div class="taxonomy-block"><p class="tax-desc">${esc(tax.description || '')}</p>${cats}</div>`;
}

