.toc{background:#f8f9fa;border:1px solid #dde;padding:14pt 18pt;margin:18pt 0;border-radius:3pt}
.toc h2{font-size:11pt;border:none;text-transform:uppercase;letter-spacing:.06em;color:#333;margin-bottom:8pt}
.toc ol{margin-left:16pt;font-size:10pt;line-height:1.9}
.toc ol ol{margin-left:14pt;font-size:9.5pt}
.toc a{color:#1565c0}

/* ═══ Inline Citations ═══════════════════════════════════════════════════ */
a.cite{font-size:8.5pt;vertical-align:super;line-height:1;color:#1565c0;font-family:Arial,sans-serif;padding:0 1pt}
a.cite:hover{text-decoration:underline}

/* ═══ Theme Blocks ═══════════════════════════════════════════════════════ */
.theme-block{margin-bottom:18pt;padding-bottom:14pt;border-bottom:1px dotted #d0d0d0}
.theme-block:last-child{border-bottom:none}
.theme-body p{text-indent:1.5em}
.insight{margin:8pt 0 4pt;padding:7pt 12pt;border-radius:2pt;font-size:10.5pt}
.consensus-box{background:#e8f5e9;border-left:3pt solid #2e7d32}
.contested-box{background:#fff3e0;border-left:3pt solid #e65100}
.key-src{margin-top:6pt;font-size:9.5pt;color:#555;font-family:Arial,sans-serif}

/* ═══ Taxonomy ═══════════════════════════════════════════════════════════ */
.taxonomy-block{margin:10pt 0}
.tax-desc{margin-bottom:8pt;font-style:italic}
.tax-item{background:#f5f7fa;border:1px solid #dde;padding:7pt 10pt;margin-bottom:6pt;border-radius:2pt}
.tax-name{font-weight:bold;color:#1a3a5c;margin-right:6pt}
.tax-count{font-size:9pt;background:#1a3a5c;color:#fff;padding:1pt 5pt;border-radius:10pt;font-family:Arial,sans-serif}
.tax-item p{margin-top:4pt;margin-bottom:0;text-indent:0;font-size:10.5pt}

/* ═══ Research Gaps ══════════════════════════════════════════════════════ */
.gap-card{background:#fffdf0;border:1px solid #f0d070;border-left:4pt solid #f0a500;padding:9pt 12pt;margin:8pt 0;border-radius:2pt}
.gap-header{display:flex;align-items:center;gap:6pt;margin-bottom:5pt;flex-wrap:wrap}
.gap-num{font-weight:bold;font-size:10.5pt;color:#7b5800}
.gap-type-tag{background:#7b5800;color:#fff;font-size:8pt;padding:1pt 5pt;border-radius:10pt;font-family:Arial,sans-serif;text-transform:capitalize}
.ev-strength{font-size:8pt;padding:1pt 5pt;border-radius:10pt;font-family:Arial,sans-serif}
.ev-strong{background:#e8f5e9;color:#1b5e20}
.ev-moderate{background:#fff3e0;color:#e65100}
.ev-weak{background:#fce4ec;color:#c62828}
.gap-text{text-indent:0;margin-bottom:4pt;font-size:10.5pt}
.gap-rationale{text-indent:0;font-size:10pt;color:#555;margin-bottom:3pt}
.gap-src{text-indent:0;font-size:9.5pt;color:#666;font-family:Arial,sans-serif}

/* ═══ Future Directions ══════════════════════════════════════════════════ */
.future-card{background:#f1f8e9;border-left:4pt solid #33691e;padding:8pt 12pt;margin:6pt 0;border-radius:2pt;font-size:10.5pt}

/* ═══ Literature Matrix ══════════════════════════════════════════════════ */
.table-wrap{overflow-x:auto;margin:10pt 0}
.mt{width:100%;border-collapse:collapse;font-size:8pt;font-family:Arial,sans-serif}
.mt th{background:#1a3a5c;color:#fff;padding:5pt 4pt;text-align:left;border:1px solid #0d2241;white-space:nowrap}
.mt td{padding:4pt;border:1px solid #d0d0d0;vertical-align:top}
.mt td.tc{font-size:7.5pt;max-width:160px}
.mt td.lim-col{font-size:7.5pt;max-width:140px}
.mt td.num-col{text-align:right;white-space:nowrap}
.mt tr:nth-child(even){background:#f8f9fa}
.mt tr:hover{background:#e8f0fb}
.score-badge{font-size:8pt;font-weight:bold;border:1px solid;padding:0 3pt;border-radius:2pt}
.score-na{color:#999}
.cat-tag{background:#e8eaf6;color:#1a237e;font-size:7.5pt;padding:1pt 4pt;border-radius:2pt;white-space:nowrap}
.oa-m{background:#1b5e20;color:#fff;font-size:7pt;padding:0 3pt;border-radius:2pt;font-family:Arial,sans-serif}

/* ═══ Charts ═════════════════════════════════════════════════════════════ */
.charts-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:20pt;margin:12pt 0}
.chart-fig{background:#fafbfc;border:1px solid #e0e4ea;border-radius:4pt;padding:10pt;page-break-inside:avoid}
.chart-svg{width:100%;height:auto;display:block}
figcaption{font-size:8.5pt;color:#555;text-align:center;margin-top:6pt;font-family:Arial,sans-serif;font-style:italic}

/* ═══ Evidence Cards ═════════════════════════════════════════════════════ */
.ev-card{border:1px solid #d0d8e4;border-radius:4pt;padding:10pt 12pt;margin:8pt 0;page-break-inside:avoid;background:#fafcff}
.ev-card:target{background:#fffde7;border-color:#f0a500}
.ev-card-head{display:flex;align-items:center;gap:5pt;flex-wrap:wrap;margin-bottom:5pt}
.ev-ref{font-family:Arial,sans-serif;font-size:9pt;font-weight:bold;color:#1a3a5c;min-width:28pt}
.ev-src-tag{font-size:7.5pt;padding:1pt 6pt;border-radius:10pt;color:#fff;font-family:Arial,sans-serif;white-space:nowrap}
.oa-badge{background:#1b5e20;color:#fff;font-size:7.5pt;padding:1pt 5pt;border-radius:10pt;font-family:Arial,sans-serif}
.ver-badge{background:#0d47a1;color:#fff;font-size:7.5pt;padding:1pt 5pt;border-radius:10pt;font-family:Arial,sans-serif}
.ev-score{font-size:8pt;font-weight:bold;font-family:Arial,sans-serif;padding:0 3pt}
.ev-title{font-size:10.5pt;font-weight:bold;margin-bottom:3pt;line-height:1.35}
.ev-title a{color:#1a1a1a}
.ev-title a:hover{color:#1565c0}
.ev-meta{font-size:8.5pt;color:#555;font-family:Arial,sans-serif;margin-bottom:5pt;text-indent:0}
.ev-abstract{font-size:9.5pt;color:#333;margin-bottom:5pt;text-indent:0;border-left:2pt solid #d0d8e4;padding-left:8pt;font-style:italic}
.ev-section{font-size:9.5pt;margin-bottom:4pt;text-indent:0}
.ev-section ul{margin:3pt 0 2pt 16pt}
.ev-section li{margin-bottom:1pt}
.ev-lim{color:#7b1a1a}
.ev-fut{color:#1b4f1b}
.doi-link{font-size:8pt;font-family:Arial,sans-serif}

/* ═══ References ═════════════════════════════════════════════════════════ */
.ref-entry{font-size:9.5pt;text-indent:-2em;padding-left:2em;margin-bottom:5pt;line-height:1.5;text-align:left;font-family:Arial,sans-serif}
.ref-entry a{color:#1565c0}

/* ═══ Disclosure ═════════════════════════════════════════════════════════ */
.disclosure{background:#e8eaf6;border:1px solid #9fa8da;padding:10pt 14pt;margin:18pt 0;font-size:9pt;font-family:Arial,sans-serif;border-radius:3pt;line-height:1.5}
.disclosure strong{color:#1a237e}

/* ═══ Chapter break ══════════════════════════════════════════════════════ */
.chapter-break{page-break-before:always}
.unavail{color:#888;font-style:italic}
</style>
</head>
<body>

<!-- ══ DOCUMENT HEADER ══════════════════════════════════════════════════════ -->
<header class="doc-header">
  <h1>${esc(topic)}</h1>
  ${discipline ? `<div style="font-size:10pt;color:#555;font-style:italic;margin-bottom:4pt">${esc(discipline)} Literature Review</div>` : ''}
  <div class="doc-meta">
    <strong>Generated:</strong> ${generatedDate}
    <span class="sep">|</span>
    <strong>Papers:</strong> ${papers.length}
    <span class="sep">|</span>
    <strong>Year range:</strong> ${minYear}–${maxYear}
    <span class="sep">|</span>
    <strong>Format:</strong> ${esc(data.citation_format || 'APA 7')}
    <span class="sep">|</span>
    <strong>Report ID:</strong> <code>${esc(data.research_id)}</code>
  </div>
</header>

<!-- ══ ABSTRACT ══════════════════════════════════════════════════════════════ -->
<section id="abstract">
<div class="abstract-box">
  <p><span class="abs-label">Abstract</span>${linkCite(synthesis.executive_summary || 'Literature review generated from ' + papers.length + ' papers retrieved from ' + sources.join(', ') + '. Synthesis and gap analysis conducted with AI assistance.')}</p>
</div>
</section>

<!-- ══ KEY METRICS ═══════════════════════════════════════════════════════════ -->
<div class="stats-row" aria-label="Summary statistics">
  <div class="stat-card"><div class="stat-n">${papers.length}</div><div class="stat-l">Papers</div></div>
  <div class="stat-card"><div class="stat-n">${maxYear - minYear + 1}</div><div class="stat-l">Year Span</div></div>
  <div class="stat-card"><div class="stat-n">${sources.length}</div><div class="stat-l">Databases</div></div>
  <div class="stat-card"><div class="stat-n">${avgCitations.toLocaleString()}</div><div class="stat-l">Avg. Citations</div></div>
  <div class="stat-card"><div class="stat-n">${openAccessCount}</div><div class="stat-l">Open Access</div></div>
  <div class="stat-card"><div class="stat-n">${(synthesis.thematic_sections || []).length}</div><div class="stat-l">Themes</div></div>
</div>

${buildToC()}

<!-- ══ CHAPTER 1: INTRODUCTION ═══════════════════════════════════════════════ -->
<section id="sec-intro" ${isFullReport ? 'class="chapter-break"' : ''}>
${ch(1, 'Introduction', 'sec-intro-h')}
<div>${linkCite(synthesis.introduction || 'Introduction not generated. See executive summary above.')}</div>
</section>

<!-- ══ CHAPTER 2: BACKGROUND ═════════════════════════════════════════════════ -->
<section id="sec-bg">
${ch(2, 'Background &amp; Theoretical Framework', 'sec-bg-h')}
<div>${linkCite(synthesis.background || 'Background section not generated.')}</div>
${synthesis.taxonomy ? `<h3>Literature Taxonomy</h3>${taxonomyHTML()}` : ''}
</section>

<!-- ══ CHAPTER 3: THEMATIC ANALYSIS ══════════════════════════════════════════ -->
<section id="sec-thematic">
${ch(3, 'Thematic Analysis', 'sec-thematic-h')}
${thematicHTML()}
</section>

<!-- ══ CHAPTER 4: COMPARATIVE ANALYSIS ══════════════════════════════════════ -->
<section id="sec-compare">
${ch(4, 'Comparative Analysis', 'sec-compare-h')}
<div>${linkCite(synthesis.comparison_analysis || 'Comparative analysis not generated.')}</div>
</section>

<!-- ══ CHAPTER 5: METHODOLOGICAL TRENDS ══════════════════════════════════════ -->
<section id="sec-methods">
${ch(5, 'Methodological Trends', 'sec-methods-h')}
<div>${linkCite(synthesis.methodological_trends || 'Methodological trends not generated.')}</div>
</section>

<!-- ══ CHAPTER 6: RESEARCH GAPS ══════════════════════════════════════════════ -->
<section id="sec-gaps">
${ch(6, 'Research Gaps', 'sec-gaps-h')}
${gaps.overall_assessment ? `<p>${linkCite(gaps.overall_assessment)}</p>` : ''}
${gapsHTML()}
${gaps.confidence_note ? `<p class="unavail" style="margin-top:8pt;font-size:10pt">${esc(gaps.confidence_note)}</p>` : ''}
</section>

<!-- ══ CHAPTER 7: FUTURE DIRECTIONS ══════════════════════════════════════════ -->
<section id="sec-future">
${ch(7, 'Future Directions', 'sec-future-h')}
${(synthesis.future_directions || []).length
  ? (synthesis.future_directions || []).map((d, i) => `<div class="future-card"><strong>Direction ${i+1}:</strong> ${linkCite(d)}</div>`).join('\n')
  : '<p class="unavail">Future directions not generated.</p>'}
</section>

<!-- ══ CHAPTER 8: CONCLUSION ══════════════════════════════════════════════════ -->
<section id="sec-conclusion">
${ch(8, 'Conclusion', 'sec-conclusion-h')}
<div>${linkCite(synthesis.conclusion || 'Conclusion not generated.')}</div>
${synthesis.confidence_statement ? `<p style="margin-top:10pt;font-style:italic;font-size:10.5pt;color:#555">${esc(synthesis.confidence_statement)}</p>` : ''}
</section>

<!-- ══ REFERENCES ══════════════════════════════════════════════════════════════ -->
<section id="sec-refs" class="${isFullReport ? 'chapter-break' : ''}">
<h2>References</h2>
<div>
${citations.map((c, i) =>
  `<p class="ref-entry" id="ref-${i+1}">${esc(c.citation)}${c.doi ? ` <a href="https://doi.org/${esc(c.doi)}" target="_blank" rel="noopener" class="doi-link">↗</a>` : ''}</p>`
).join('\n')}
</div>
</section>

<!-- ══ APPENDIX A: LITERATURE MATRIX ══════════════════════════════════════════ -->
<section id="appA" class="${isFullReport ? 'chapter-break' : ''}">
<h2>Appendix A — Literature Matrix</h2>
<p style="font-size:9.5pt;color:#555;margin-bottom:8pt;text-indent:0">Comparative table for ${papers.length} papers. Click <strong>[N]</strong> in Ref column to jump to the evidence card. Scores are AI estimates (1–10). OA = Open Access.</p>
${matrixHTML()}
</section>

<!-- ══ APPENDIX B: EVIDENCE CARDS ═════════════════════════════════════════════ -->
<section id="appB" class="${isFullReport ? 'chapter-break' : ''}">
<h2>Appendix B — Evidence Cards</h2>
<p style="font-size:9.5pt;color:#555;margin-bottom:10pt;text-indent:0">Individual evidence cards for each paper. Inline citations in the main text link here. Click titles to open source pages. DOI links are verified where available.</p>
${evidenceCards()}
</section>

<!-- ══ APPENDIX C: BIBLIOMETRIC CHARTS ════════════════════════════════════════ -->
<section id="appC" class="${isFullReport ? 'chapter-break' : ''}">
<h2>Appendix C — Bibliometric Analysis</h2>
<p style="font-size:9.5pt;color:#555;margin-bottom:10pt;text-indent:0">Auto-generated visualisations derived from the retrieved paper metadata. All charts are SVG and print cleanly.</p>
<div class="charts-grid">
${yearHistogramSVG()}
${sourceBarSVG()}
${categoryBarSVG()}
${scatterSVG()}
${citationHistSVG()}
</div>
</section>

<!-- ══ AI DISCLOSURE ═══════════════════════════════════════════════════════════ -->
<div class="disclosure no-print">
  <strong>AI Use Disclosure</strong><br>
  This literature review was generated with AI assistance using <strong>${esc(aiDisclosure.model || aiDisclosure.tool || 'an AI language model')}</strong>.
  Databases queried: ${esc(sources.join(', ') || 'multiple')}. AI-assisted activities: ${esc((aiDisclosure.activities || []).join(', ') || 'query refinement, paper analysis, synthesis, citation formatting')}.
  <br><strong>Important:</strong> ${esc(aiDisclosure.limitations || 'All citations must be independently verified before academic use. This report is based on abstract-only analysis. Scores are AI estimates. The researcher is responsible for evaluating accuracy and completeness.')}
  ${feedback ? `<br><strong>Reviewer feedback:</strong> ${esc(feedback)}` : ''}
</div>

</body>
</html>`;

return {
  json: {
    html_content: html,
    topic: data.topic,
    research_id: data.research_id,
    total_papers: papers.length,
    generated_at: new Date().toISOString()
  }
};

const data = $('Assemble Complete Review Data').first().json;
const validateData = $('Validate & Configure').first().json;
const synthesis = data.synthesis || {};
const papers = data.papers || [];
const citations = data.citations || [];
const gaps = data.gaps || {};
const feedback = $('Human Review Gate').first().json.body?.feedback || '';
const isFullReport = (validateData.report_format || 'Standard Summary').includes('Full');

const topic = data.topic || 'Literature Review';
const generatedAt = new Date().toISOString();
const sources = [...new Set(papers.map(p => p.source).filter(Boolean))];
const years = papers.map(p => parseInt(p.year)).filter(y => !isNaN(y));
const minYear = years.length > 0 ? Math.min(...years) : '—';
const maxYear = years.length > 0 ? Math.max(...years) : '—';

// Strip HTML tags that may appear in linkCite output for Markdown
function stripHtml(str) {
  if (!str) return '';
  return str.replace(/<[^>]+>/g, '');
}

function h(level, text) {
  return '#'.repeat(level) + ' ' + text;
}

let md = '';

// ── Front matter ──────────────────────────────────────────────────────────────
md += `# ${topic}\n\n`;
md += `> **Literature Review** | Generated: ${generatedAt.substring(0,10)}\n`;
md += `> Papers: **${papers.length}** | Databases: ${sources.join(', ')} | Years: ${minYear}–${maxYear} | Format: ${data.citation_format || 'APA 7'}\n`;
md += `> Research ID: \`${data.research_id || 'unknown'}\`\n\n`;
md += `---\n\n`;

// ── Abstract ──────────────────────────────────────────────────────────────────
md += `## Abstract\n\n`;
md += stripHtml(synthesis.executive_summary || `Literature review of ${papers.length} papers from ${sources.join(', ')}.`) + '\n\n';
md += `---\n\n`;

// ── Table of Contents ─────────────────────────────────────────────────────────
if (isFullReport) {
  md += `## Table of Contents\n\n`;
  md += `1. [Introduction](#introduction)\n`;
  md += `2. [Background & Theoretical Framework](#background--theoretical-framework)\n`;
  md += `3. [Thematic Analysis](#thematic-analysis)\n`;
  const themes = synthesis.thematic_sections || [];
  themes.forEach((s, i) => {
    md += `   ${i+1}. [${s.title || 'Theme ' + (i+1)}](#${(s.title || 'theme-' + (i+1)).toLowerCase().replace(/\s+/g,'-').replace(/[^a-z0-9-]/g,'')})\n`;
  });
  md += `4. [Comparative Analysis](#comparative-analysis)\n`;
  md += `5. [Methodological Trends](#methodological-trends)\n`;
  md += `6. [Research Gaps](#research-gaps)\n`;
  md += `7. [Future Directions](#future-directions)\n`;
  md += `8. [Conclusion](#conclusion)\n`;
  md += `9. [References](#references)\n`;
  md += `10. [Appendix A — Literature Matrix](#appendix-a--literature-matrix)\n`;
  md += `11. [Appendix B — Evidence Cards](#appendix-b--evidence-cards)\n\n`;
  md += `---\n\n`;
}

// ── Chapter 1: Introduction ───────────────────────────────────────────────────
if (isFullReport) md += `## Chapter 1 — Introduction\n\n`;
else md += `## Introduction\n\n`;
md += stripHtml(synthesis.introduction || 'Introduction not generated.') + '\n\n';

// ── Chapter 2: Background ─────────────────────────────────────────────────────
if (isFullReport) md += `## Chapter 2 — Background & Theoretical Framework\n\n`;
else md += `## Background\n\n`;
md += stripHtml(synthesis.background || 'Background not generated.') + '\n\n';

if (synthesis.taxonomy?.categories?.length) {
  md += `### Literature Taxonomy\n\n`;
  md += synthesis.taxonomy.description ? synthesis.taxonomy.description + '\n\n' : '';
  synthesis.taxonomy.categories.forEach(c => {
    md += `**${c.name}** (${c.paper_count || 0} papers): ${c.description}\n\n`;
  });
}

// ── Chapter 3: Thematic Analysis ─────────────────────────────────────────────
if (isFullReport) md += `## Chapter 3 — Thematic Analysis\n\n`;
else md += `## Thematic Analysis\n\n`;

const themes = synthesis.thematic_sections || [];
if (!themes.length) {
  md += `*Thematic analysis not available for ${papers.length} retrieved papers.*\n\n`;
} else {
  themes.forEach((s, i) => {
    md += `### ${isFullReport ? '3.' + (i+1) + ' ' : ''}${s.title || 'Theme ' + (i+1)}\n\n`;
    md += stripHtml(s.content || '') + '\n\n';
    if (s.consensus_view) md += `> **Consensus:** ${stripHtml(s.consensus_view)}\n\n`;
    if (s.contested_areas) md += `> **Contested:** ${stripHtml(s.contested_areas)}\n\n`;
    if (s.key_papers?.length) md += `**Key sources:** ${s.key_papers.slice(0,4).map(t => `*${t}*`).join('; ')}\n\n`;
  });
}

// ── Chapter 4: Comparative Analysis ──────────────────────────────────────────
if (isFullReport) md += `## Chapter 4 — Comparative Analysis\n\n`;
else md += `## Comparative Analysis\n\n`;
md += stripHtml(synthesis.comparison_analysis || 'Comparative analysis not generated.') + '\n\n';

// ── Chapter 5: Methodological Trends ─────────────────────────────────────────
if (isFullReport) md += `## Chapter 5 — Methodological Trends\n\n`;
else md += `## Methodological Trends\n\n`;
md += stripHtml(synthesis.methodological_trends || 'Methodological trends not generated.') + '\n\n';

// ── Chapter 6: Research Gaps ──────────────────────────────────────────────────
if (isFullReport) md += `## Chapter 6 — Research Gaps\n\n`;
else md += `## Research Gaps\n\n`;
if (gaps.overall_assessment) md += stripHtml(gaps.overall_assessment) + '\n\n';

const allGaps = [...(gaps.empirical_gaps || []), ...(gaps.theoretical_gaps || []), ...(gaps.methodological_gaps || [])];
const gapList = allGaps.length > 0 ? allGaps : (gaps.priority_gaps || synthesis.research_gaps || []);

if (!gapList.length) {
  md += '*No specific research gaps identified. Full-text review recommended.*\n\n';
} else {
  gapList.forEach((g, i) => {
    const gapText = typeof g === 'string' ? g : (g.gap || JSON.stringify(g));
    const gType = typeof g === 'object' && g.type ? ` *(${g.type})*` : '';
    const strength = typeof g === 'object' && g.evidence_strength ? ` [${g.evidence_strength}]` : '';
    md += `**Gap ${i+1}${gType}${strength}:** ${stripHtml(gapText)}\n\n`;
    if (typeof g === 'object' && g.rationale) md += `  *Rationale:* ${stripHtml(g.rationale)}\n\n`;
  });
}

// ── Chapter 7: Future Directions ──────────────────────────────────────────────
if (isFullReport) md += `## Chapter 7 — Future Directions\n\n`;
else md += `## Future Directions\n\n`;
(synthesis.future_directions || []).forEach((d, i) => {
  md += `${i+1}. ${stripHtml(d)}\n`;
});
if (!(synthesis.future_directions || []).length) md += '*Future directions not generated.*\n';
md += '\n';

// ── Chapter 8: Conclusion ─────────────────────────────────────────────────────
if (isFullReport) md += `## Chapter 8 — Conclusion\n\n`;
else md += `## Conclusion\n\n`;
md += stripHtml(synthesis.conclusion || 'Conclusion not generated.') + '\n\n';
if (synthesis.confidence_statement) {
  md += `> *${synthesis.confidence_statement}*\n\n`;
}

md += `---\n\n`;

// ── References ────────────────────────────────────────────────────────────────
md += `## References\n\n`;
citations.forEach((c, i) => {
  md += `${i+1}. ${c.citation}${c.doi ? ` https://doi.org/${c.doi}` : ''}\n\n`;
});

md += `---\n\n`;

// ── Appendix A: Literature Matrix ─────────────────────────────────────────────
md += `## Appendix A — Literature Matrix\n\n`;
md += `| # | Authors | Year | Title | Category | Inn. | Rel. | Citations |\n`;
md += `|---|---------|------|-------|----------|------|------|----------|\n`;
papers.slice(0, 50).forEach((p, i) => {
  const auth = (p.authors || '').split(',')[0].trim() + ((p.authors || '').includes(',') ? ' et al.' : '');
  const title = (p.title || '').substring(0, 55) + ((p.title || '').length > 55 ? '…' : '');
  const cat = p.analysis?.paper_category || '—';
  const inn = p.analysis?.innovation_score != null ? p.analysis.innovation_score : '—';
  const rel = p.analysis?.relevance_score != null ? p.analysis.relevance_score : '—';
  const cit = p.citations || 0;
  md += `| [${i+1}] | ${auth} | ${p.year || '—'} | ${title} | ${cat} | ${inn} | ${rel} | ${cit} |\n`;
});
md += '\n';

// ── Appendix B: Evidence Cards ────────────────────────────────────────────────
md += `## Appendix B — Evidence Cards\n\n`;
papers.slice(0, 50).forEach((p, i) => {
  const a = p.analysis || {};
  md += `### [${i+1}] ${p.title || 'Unknown'}\n\n`;
  md += `**Authors:** ${p.authors || '—'} · **Year:** ${p.year || '—'} · **Source:** ${p.source || '—'}`;
  if (p.journal) md += ` · **Journal:** ${p.journal}`;
  if (p.citations) md += ` · **Citations:** ${p.citations.toLocaleString()}`;
  if (p.doi) md += ` · **DOI:** https://doi.org/${p.doi}`;
  if (p.url) md += ` · [Open paper](${p.url})`;
  md += '\n\n';
  if (p.abstract && p.abstract !== 'Abstract not available') {
    md += `> ${p.abstract.substring(0, 400)}${p.abstract.length > 400 ? '…' : ''}\n\n`;
  }
  if (a.key_findings?.length) {
    md += `**Key findings:**\n`;
    a.key_findings.slice(0,4).forEach(f => { md += `- ${f}\n`; });
    md += '\n';
  }
  if (a.methodology) md += `**Methodology:** ${a.methodology}\n\n`;
  if (a.limitations?.length) md += `**Limitations:** ${a.limitations[0]}\n\n`;
  if (a.innovation_score != null) md += `**Scores:** Innovation ${a.innovation_score}/10 · Relevance ${a.relevance_score || '—'}/10\n\n`;
  md += '---\n\n';
});

// ── Footer ────────────────────────────────────────────────────────────────────
md += `\n---\n\n`;
md += `> **AI Disclosure:** This review was generated with AI assistance. All citations must be independently verified before academic use. Analysis is based on abstracts only — full-text review is recommended for publication-grade work.\n`;
if (feedback) md += `> **Reviewer feedback:** ${feedback}\n`;

return { json: { markdown_content: md, topic: data.topic, research_id: data.research_id } };

const data = $('Assemble Complete Review Data').first().json;
const feedback = $('Human Review Gate').first().json.body?.feedback || '';
const exportData = {
  _metadata: { export_version: '2.0.0', tool: 'Research Intelligence n8n', generated_at: new Date().toISOString() },
