={{ (function(){
  var md = $('Compile Delivery Package').first().json.markdown_content || '';
  // Split into chunks of max 40000 chars (Docs API limit per request)
  var chunks = [];
  var chunkSize = 40000;
  for(var i = 0; i < md.length; i += chunkSize) {
    chunks.push({ insertText: { location: { index: chunks.length === 0 ? 1 : 999999 }, text: md.slice(i, i + chunkSize) } });
  }
  if(!chunks.length) chunks = [{ insertText: { location: { index: 1 }, text: 'No content available.' } }];
  return JSON.stringify({ requests: [chunks[0]] });
})() }}

