const compileData = $('Compile Delivery Package').first().json;
const googleDocId = $('Create Google Doc').first()?.json?.documentId || null;
const googleDocUrl = googleDocId
  ? 'https://docs.google.com/document/d/' + googleDocId + '/edit?usp=sharing'
  : null;

const docSection = googleDocUrl
  ? '<div style="background:#e8f5e9;padding:16px;border-radius:8px;margin:16px 0;"><p style="margin:0"><strong>📄 Open in Google Docs:</strong> <a href="' + googleDocUrl + '">' + googleDocUrl + '</a></p></div>'
  : '';

const emailBody = '<html><body style="font-family:Arial,sans-serif;max-width:900px;margin:0 auto;padding:24px">'
  + '<h1 style="color:#1a1a1a;border-bottom:3px solid #4CAF50;padding-bottom:12px">Literature Review Complete</h1>'
  + '<table style="width:100%;border-collapse:collapse;margin-bottom:24px">'
  + '<tr><td style="padding:8px;color:#555"><strong>Topic</strong></td><td style="padding:8px">' + compileData.topic + '</td></tr>'
  + '<tr style="background:#f9f9f9"><td style="padding:8px;color:#555"><strong>Papers Analyzed</strong></td><td style="padding:8px">' + compileData.total_papers + '</td></tr>'
  + '<tr><td style="padding:8px;color:#555"><strong>Research ID</strong></td><td style="padding:8px"><code>' + compileData.research_id + '</code></td></tr>'
  + '<tr style="background:#f9f9f9"><td style="padding:8px;color:#555"><strong>Generated</strong></td><td style="padding:8px">' + new Date(compileData.generated_at).toLocaleString() + '</td></tr>'
  + '</table>'
  + docSection
  + '<hr style="margin:24px 0"/>'
  + compileData.html_content
  + '</body></html>';

return {
  json: {
    ...compileData,
    document_id: googleDocId,
    google_doc_url: googleDocUrl,
    email_body: emailBody
  }
};

const data = $input.first().json;
const deliveries = [];
if (data.google_doc_url) deliveries.push('Google Docs: ' + data.google_doc_url);
if (data.email_sent) deliveries.push('Email sent to: ' + data.recipient_email);
if (!deliveries.length) deliveries.push('Saved to server only');

console.log('Delivery complete for research_id:', data.research_id);
console.log('Deliveries:', deliveries.join(' | '));

return {
  json: {
    research_id: data.research_id,
    topic: data.topic,
    total_papers: data.total_papers,
    recipient_email: data.recipient_email,
    delivery_method: data.delivery_method,
    google_doc_url: data.google_doc_url,
    email_sent_to: data.recipient_email,
    deliveries: deliveries,
    completed_at: new Date().toISOString()
  }
};
